// Local assets as safe fallback in case of network offline
const localImages = import.meta.glob<string>('@/assets/images/**/*.{jpg,jpeg,png,webp}', {
  eager: true,
  import: 'default',
});

const localVideos = import.meta.glob<string>('@/assets/videos/**/*.{mp4,webm,mov}', {
  eager: true,
  import: 'default',
});

/**
 * Returns the exact 200 OK Cloudinary URL for any requested image filename
 */
export const getCloudinaryImage = (imagePath: string): string => {
  if (!imagePath) return '';
  if (/^(https?:|\/\/|data:)/.test(imagePath)) return imagePath;

  const clean = imagePath.replace(/^\/+/, '');
  const fileName = clean.split('/').pop() || clean;

  if (CLOUDINARY_IMAGES_MAP[clean]) {
    return CLOUDINARY_IMAGES_MAP[clean];
  }
  if (CLOUDINARY_IMAGES_MAP[fileName]) {
    return CLOUDINARY_IMAGES_MAP[fileName];
  }

  // Fallback to local image
  return getLocalImageFallback(clean);
};

/**
 * Returns the Cloudinary video URL.
 * Pass optimize: true (or quality options) to stream lightweight, fast-loading MP4 (e.g. 800KB instead of 25MB+)
 * to avoid browser lag, freezing, and memory saturation.
 */
export const getCloudinaryVideo = (
  videoPath: string,
  options?: { optimize?: boolean; width?: number; quality?: 'low' | 'eco' | 'good' | 'auto' }
): string => {
  if (!videoPath) return '';
  if (/^(https?:|\/\/|data:)/.test(videoPath)) return videoPath;

  const clean = videoPath.replace(/^\/+/, '');
  const fileName = clean.split('/').pop() || clean;

  let url = CLOUDINARY_VIDEOS_MAP[clean] || CLOUDINARY_VIDEOS_MAP[fileName] || '';

  if (url) {
    if (options?.optimize) {
      const q = options.quality || 'eco';
      const w = options.width || 480;
      // Injects Cloudinary on-the-fly video optimization params
      return url.replace('/video/upload/', `/video/upload/q_auto:${q},w_${w},c_limit,vc_h264/`);
    }
    return url;
  }

  // Fallback to local video
  return getLocalVideoFallback(clean);
};

/**
 * Extracts and returns the exact middle position frame (50% timestamp) of the video as a lightweight cover thumbnail.
 * Cloudinary generates this on-the-fly using so_50p (start offset 50 percent).
 */
export const getCloudinaryVideoThumbnail = (
  videoPath: string,
  options?: { width?: number; quality?: 'auto' | 'low' | 'good' }
): string => {
  if (!videoPath) return '';
  const clean = videoPath.replace(/^\/+/, '');
  const fileName = clean.split('/').pop() || clean;

  const url = CLOUDINARY_VIDEOS_MAP[clean] || CLOUDINARY_VIDEOS_MAP[fileName] || '';
  if (url) {
    const w = options?.width || 480;
    const q = options?.quality || 'auto';
    // Extracts exact 50% middle position frame and converts to lightweight JPEG
    return url
      .replace('/video/upload/', `/video/upload/so_50p,w_${w},q_${q}/`)
      .replace(/\.(mp4|webm|mov|mkv)$/i, '.jpg');
  }

  return '';
};

/**
 * Resolve local image fallback by path/filename
 */
export const getLocalImageFallback = (imagePath: string): string => {
  const clean = imagePath.replace(/^\/+/, '');
  for (const [k, v] of Object.entries(localImages)) {
    if (k.endsWith(clean)) return v;
  }
  return '';
};

/**
 * Resolve local video fallback by filename
 */
export const getLocalVideoFallback = (videoPath: string): string => {
  const clean = videoPath.replace(/^\/+/, '');
  for (const [k, v] of Object.entries(localVideos)) {
    if (k.endsWith(clean)) return v;
  }
  return '';
};

export default {
  images: CLOUDINARY_IMAGES_MAP,
  videos: CLOUDINARY_VIDEOS_MAP,
  getImage: getCloudinaryImage,
  getVideo: getCloudinaryVideo,
  getLocalImageFallback,
  getLocalVideoFallback,
};
